@ExceptionHandler(DataIntegrityViolationException.class)
ProblemDetail onDataError(DataIntegrityViolationException e) {
    Throwable cause = e.getMostSpecificCause();
    String constraint = cause instanceof PSQLException pe
            && pe.getServerErrorMessage() != null
            ? pe.getServerErrorMessage().getConstraint() : null;  // tên constraint, không có giá trị
    log.warn("data error: sqlState={} constraint={}",
            cause instanceof SQLException se ? se.getSQLState() : null, constraint);
    return switch (constraint == null ? "" : constraint) {
        case "customers_phone_key" -> problem(CONFLICT, "Số điện thoại đã được đăng ký");
        case "customers_age_check" -> problem(UNPROCESSABLE_CONTENT, "Phải đủ 18 tuổi");
        default -> problem(CONFLICT, "Dữ liệu không hợp lệ");
    };
}

